namespace OpenTPW;

/// <summary>
/// The path builder's approximation register (docs/PATHS.md; docs/reverse/PATH-plan.md §10). Each entry is
/// tagged <c>[APPROX:PATH-NNN]</c> at its code site and names the plan's unknown in its first word. Everything
/// else in the path builder is traced from the Mac binary (BIN labels at the code sites).
/// </summary>
public static class PathApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("PATH-007", "PATH-LAND: the land follows the original's own routines, run on a layer of structure records (FenceEngine): the level's fence is laid by the setup 0x5323f0 (the click handler's mode 0x19 through the line walker 0x53aac0 and step 0x5370e0, the mark 0x531040, the fill 0x5311c0 with its ring walk by direction bit and its stride-2 scan, the walk 0x52ba50 and the strip at the gate), Buy Land validates (0x531a50), prices (0x532303) and purchases by the same routines (0x5327e0: five clicks, walk, mark, fill, unmark), and an imported save keeps its saved flags and structure records (0x4d0b30); the four restart.INTS saves and 18 oracle-run fences and purchases are reproduced cell for cell. Residual: a purchase on which the original's fill reads the cell beyond the map's edge (a null cell, a crash) or whose ring walk never ends (a post-less cell) is refused and charges nothing, where the original crashes or hangs (report: the open side of the gate, e.g. Jungle (45, 11)-(49, 17)); the six-click fence (bit 0x400 of the level word 0x79d86c, copied from the options word 0x78d954 by 0x449e78) is laid by the engine but nothing sets the bit, whose source is not traced; a fence cell that holds a foreign structure (a track tile on the lattice) takes the click handler's other branches, which the oracle did not run; a save without its structure records (an OpenTPW save before this port) derives the layer from its ring"),
		("PATH-015", "QUEUE-MODELS: queue cells carry the theme's queue models as tp.exe places them (chooser 0x535dd0 class 2 from the cell's link byte, table 0x7630b0; models of 0x522900 at yaw 360 minus the rotation, 0x5229e0; no ground tile, 0x5365d0), baked into static batches with each vertex draped onto the landscape as tp.exe does it (0x469a80, QueueModelDrape), the cell a hole of the ground (0x46df50) and, as an object's base is, the skirt read at load (the opaque slot, the normalised coordinates, 0x46aa10) and, with the procedural terrain textures on, the skirt word and the composite floor of the art over the cell's procedural ground (0x463060, 0x57ace0); without the animation of their texture frames (the fire0 torches) and the load flag 0x100000 of the two quedead entries"),
		("PATH-017", "PATH-PAUSE-WINDOW: the ordinary-WM pump (bounded admission then drain: topmost eligible receiver, stable screen/element lifetime, separate movement capture, saved release owner) is implemented; the pause key P (tp.exe 0x40bf70 → 0x409350(1)) toggles a window (the global handle 0x7cb2cc, 0x4a27f0 → 0x47ed80; the offline focus-loss pause 0x4092a0(1) → 0x4a2790 builds it too): a full-screen layer (0x65dd7b(1, 1, 1, 0, 0, 0x7ff, 0x5ff), flags 1, the 'lolight' backdrop) appended as the last child of the root, under the panel 5094 (174,500)-(1874,900) of table 0x752e00. The hit test 0x65db25 takes a shown window with flag bit 1 and lets the last such child win (0x65dd7b appends a new window after its siblings), so the layer is the hit window of every point and, with the focus (0x65e59b), of every key over the windows that existed when it was built; its procedure 0x4a2680 uses only the P key and the panel's animation (0x65e72d, table 0x752ed0) and hands the rest to the default procedure 0x65f6d1, which forwards nothing, so the park click handler 0x4879d0 (called only from the HUD window's procedure, 0x488768) and the camera's input 0x42a760 (called only by the procedures of the HUD, the hidden-HUD overlay and the chat mode) get no message under it; the click route and the camera follow that here, and OpenTPW's speed pause (the HUD's speed buttons, the numpad, a park loaded paused) builds no layer, as 0x409350 is the only builder besides the focus loss. Not ported: alternate buffered input, the aggregate wheel and the keys other than P of the screens below the layer (they still act), the original backdrop and panel rendering, and whether a path or pool drag released over the HUD uses the stored hover cell (the click dispatcher 0x4879d0 takes no message coordinates and acts on the stored cursor mode 0x7b05d8) (evidence needed: a capture of the P window over a park, the alternate buffered-input mode's pump, and the stored hover cell of a drag released over the HUD)"),
	};
}
